package com.nthexperience.desktop;
import android.app.Activity;
import android.content.*;
import android.graphics.Color;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.function.Consumer;
import org.json.*;

/** Traditional Eight Control Panel pages, with working controls and no Ten Settings shell. */
final class EightDesktopOptions extends LinearLayout {
    final DesktopStore store;final Consumer<String> open;final LinearLayout body,links;final TextView address,back;final ScrollView scroll;final AeroWallpaper desktopWallpaper;
    final ArrayList<String> history=new ArrayList<>();final Map<String,Integer> positions=new HashMap<>();int navigationGeneration;
    VistaControlPanel details;String taskbarTab="Taskbar";
    String page="themes";AeroWallpaper preview;int themeColumns=1;
    EightDesktopOptions(Context c,DesktopStore store,Consumer<String> open,AeroWallpaper desktopWallpaper){super(c);this.store=store;this.open=open;this.desktopWallpaper=desktopWallpaper;setSaveFromParentEnabled(false);setOrientation(VERTICAL);setBackgroundColor(Color.WHITE);setContentDescription("Eight desktop Control Panel");TenAppearance.preserve(this);
        LinearLayout bar=new LinearLayout(c);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(8),0,dp(8),0);back=buttonText("←",this::goBack);back.setContentDescription("Back in Control Panel");bar.addView(back,new LayoutParams(dp(40),dp(40)));address=Aero.text(c,"",12,0xff225588);bar.addView(address,new LayoutParams(0,-2,1));addView(bar,new LayoutParams(-1,dp(44)));
        LinearLayout split=new LinearLayout(c);addView(split,new LayoutParams(-1,0,1));ScrollView navigation=new ScrollView(c);navigation.setFillViewport(true);navigation.setBackgroundColor(0xfff0f0f0);links=Aero.column(c);links.setPadding(dp(9),dp(10),dp(8),dp(12));navigation.addView(links);split.addView(navigation,new LayoutParams(dp(116),-1));
        TextView panelHome=buttonText("Control Panel Home",()->navigate("themes"));links.addView(panelHome,new LayoutParams(-1,-2));for(String id:new String[]{"themes","desktop","background","colors","sound","display","taskbar"}){TextView link=buttonText(EightSettingsCatalog.title(id),()->navigate(id));link.setTextSize(12);links.addView(link,new LayoutParams(-1,-2));}
        scroll=new ScrollView(c);scroll.setFillViewport(true);scroll.setBackgroundColor(Color.WHITE);body=Aero.column(c);body.setPadding(dp(14),dp(10),dp(14),dp(20));scroll.addView(body);split.addView(scroll,new LayoutParams(0,-1,1));navigate("themes");
        addOnLayoutChangeListener((v,l,t,r,b,ol,ot,or,ob)->{int width=r-l>=dp(600)?dp(170):dp(108);if(navigation.getLayoutParams().width!=width){navigation.getLayoutParams().width=width;navigation.requestLayout();}int next=scroll.getWidth()>=dp(420)?2:1;if(page.equals("themes")&&themeColumns!=next){themeColumns=next;render();}});
    }
    int dp(int n){return Aero.dp(getContext(),n);}
    void navigate(String id){String target=EightSettingsCatalog.canonical(id);if(target.startsWith("pc:")){open.accept("eight-setting:"+target.substring(3));return;}if(target.startsWith("android:")){open.accept("setting:"+target);return;}rememberTab();positions.put(page,scroll.getScrollY());if(history.isEmpty()||!target.equals(page)){history.add(target);if(history.size()>32)history.remove(0);}page=target;render();restoreScroll(positions.getOrDefault(page,0));}
    boolean goBack(){if(history.size()<2)return false;rememberTab();positions.put(page,scroll.getScrollY());history.remove(history.size()-1);page=history.get(history.size()-1);render();restoreScroll(positions.getOrDefault(page,0));return true;}
    void restoreScroll(int y){int generation=++navigationGeneration;scroll.post(()->{if(generation==navigationGeneration)scroll.scrollTo(0,y);});}
    void refreshAppearance(){int y=scroll.getScrollY();rememberTab();render();restoreScroll(y);}
    void rememberTab(){for(int i=0;i<body.getChildCount();i++)if(body.getChildAt(i) instanceof EightTaskbarProperties)taskbarTab=((EightTaskbarProperties)body.getChildAt(i)).tab;}
    JSONObject state(){rememberTab();positions.put(page,scroll.getScrollY());JSONObject state=new JSONObject();JSONArray pages=new JSONArray();for(String id:history){JSONObject item=new JSONObject();GadgetLayout.put(item,"page",id);GadgetLayout.put(item,"scroll",positions.getOrDefault(id,0));pages.put(item);}GadgetLayout.put(state,"pages",pages);GadgetLayout.put(state,"tab",taskbarTab);return state;}
    void restore(JSONObject state){if(state==null)return;JSONArray pages=state.optJSONArray("pages");if(pages==null||pages.length()<1||pages.length()>32)return;ArrayList<String> restored=new ArrayList<>();Map<String,Integer> offsets=new HashMap<>();for(int i=0;i<pages.length();i++){JSONObject row=pages.optJSONObject(i);if(row==null)return;String id=row.optString("page");boolean known=false;for(EightSettingsCatalog.Page item:EightSettingsCatalog.PAGES)if(item.id.equals(id))known=true;if(!known)return;restored.add(id);offsets.put(id,Math.max(0,Math.min(200000,row.optInt("scroll"))));}history.clear();history.addAll(restored);positions.clear();positions.putAll(offsets);page=history.get(history.size()-1);String tab=state.optString("tab");taskbarTab=Arrays.asList("Taskbar","Navigation","Jump Lists","Toolbars").contains(tab)?tab:"Taskbar";render();restoreScroll(positions.getOrDefault(page,0));}
    void showDetails(String id){details=new VistaControlPanel(getContext(),store,desktopWallpaper,new VistaShell.Actions(){public void open(String target){EightDesktopOptions.this.open.accept(target);}public void action(String action){EightDesktopOptions.this.open.accept("setting:"+action);}},id);details.navigationHost(this::navigate);ViewGroup parent=(ViewGroup)details.content.getParent();parent.removeView(details.content);body.addView(details.content,new LayoutParams(-1,-2));}
    void refreshUsageAccess(boolean permitted){if(details!=null)details.refreshUsageAccess(permitted);}
    void wallpaperChosen(List<String> photos){if(details!=null&&page.equals("backgroundoptions"))details.wallpaperChosen(photos);}
    void appearanceChanged(){if(getContext() instanceof MainActivity)((MainActivity)getContext()).applyTenAppearance();else render();}
    void render(){if(preview!=null){preview.close();preview=null;}if(details!=null){details.close();details=null;}body.removeAllViews();back.setEnabled(history.size()>1);back.setAlpha(back.isEnabled()?1:.35f);address.setText("Control Panel  ›  "+(Arrays.asList("themes","background","colors","desktop","display","fonts").contains(page)?"Appearance and Personalization  ›  ":"")+EightSettingsCatalog.title(page));for(int i=1;i<links.getChildCount();i++)links.getChildAt(i).setBackgroundColor(((TextView)links.getChildAt(i)).getText().toString().equals(EightSettingsCatalog.title(page.equals("backgroundoptions")?"background":page.equals("taskbarapps")?"taskbar":page))?0xffe5f3fb:Color.TRANSPARENT);heading(EightSettingsCatalog.title(page));
        switch(page){
            case "themes":note("Change the visuals and sounds on your desktop");body.addView(new TenThemeGallery(getContext(),store,Math.max(dp(150),scroll.getWidth()-dp(28)),open,()->{appearanceChanged();}),new LayoutParams(-1,-2));break;
            case "background":preview=new AeroWallpaper(getContext(),store.prefs.getInt("wallpaper",11));body.addView(preview,new LayoutParams(-1,dp(150)));for(int i=0;i<DesktopBackgrounds.NAMES.length;i++){final int n=i;button(DesktopBackgrounds.NAMES[i],()->{android.content.SharedPreferences.Editor edit=store.prefs.edit();DesktopBackgrounds.choose(edit,Collections.singletonList(DesktopBackgrounds.stock(n)),n);edit.apply();appearanceChanged();});}button("Browse for a picture",()->open.accept("setting:wallpaper-browse"));button("Choose a slideshow folder",()->open.accept("setting:wallpaper-folder"));button("Picture position and slideshow options",()->navigate("backgroundoptions"));break;
            case "colors":note("Choose the color of your window borders and taskbar.");body.addView(new TenAccentPicker(getContext(),store,this::appearanceChanged),new LayoutParams(-1,-2));CheckBox aero=toggle("Enable optional Aero glass","unused",false);aero.setOnCheckedChangeListener(null);aero.setChecked(TenThemes.aero(store.prefs));aero.setOnCheckedChangeListener((v,checked)->{store.prefs.edit().putString("ten_shell_style",checked?"Aero":"Ten").apply();appearanceChanged();});if(TenThemes.aero(store.prefs))body.addView(new TenAeroColors(getContext(),store,this::appearanceChanged));button("Start screen colors",()->open.accept("eight-setting:personalize"));break;
            case "taskbar":EightTaskbarProperties properties=new EightTaskbarProperties(getContext(),store,open,this::appearanceChanged);properties.tab=taskbarTab;properties.render();body.addView(properties,new LayoutParams(-1,-2));break;
            case "desktop":body.addView(new DesktopSettings(getContext(),store,this::appearanceChanged));button("Arrange desktop shortcuts",()->open.accept("@organize"));break;
            case "display":new BrightnessControl((Activity)getContext()).content(body);button("Screen resolution and rotation",()->open.accept("setting:android:display"));button("Desktop icon size",()->navigate("desktop"));break;
            case "sound":DesktopSounds.settings(getContext(),body);button("Android sound settings",()->open.accept("setting:android:sound"));break;
            case "fonts":body.addView(new TenFonts(getContext(),store,()->{if(getContext() instanceof MainActivity)((MainActivity)getContext()).applyTenFont();}));break;
            case "multitasking":toggle("Arrange desktop windows at screen edges","ten_snap",true);note("Immersive apps use the left switcher and Snap another app command. Original Eight keeps a compact companion; 8.1 supports a movable divider.");button("Switch apps",()->open.accept("@eight-switcher"));break;
            case "storage":try{StatFs stat=new StatFs(Environment.getExternalStorageDirectory().getPath());note(android.text.format.Formatter.formatFileSize(getContext(),stat.getAvailableBytes())+" free of "+android.text.format.Formatter.formatFileSize(getContext(),stat.getTotalBytes()));}catch(RuntimeException ignored){}button("Computer",()->open.accept("@computer"));button("File access setup",()->open.accept("setting:storage-access"));button("Android storage settings",()->open.accept("setting:android:storage"));break;
            case "installed":button("Manage installed Android programs",()->open.accept("setting:android:apps"));button("All apps",()->open.accept("@allapps"));break;
            case "defaults":button("Choose default Android programs",()->open.accept("setting:android:defaults"));button("Default Home app",()->open.accept("setting:home"));break;
            case "profile":showDetails("accounts");break;
            case "motion":toggle("Reduce motion","reduce_motion",false);CheckBox status=toggle("Show Android status bar","show_status_bar",false);status.setOnCheckedChangeListener((v,on)->{store.prefs.edit().putBoolean("show_status_bar",on).apply();open.accept("setting:chrome");});button("Android accessibility",()->open.accept("setting:android:accessibility"));break;
            case "tools":for(String[] tool:new String[][]{{"@help","Help+Tips"},{"@mobility","Windows Mobility Center"},{"@paint","Paint"},{"@wordpad","WordPad"},{"@characters","Character Map"},{"@readinglist","Reading List"},{"@reader","Reader"},{"@alarms","Alarms"},{"@soundrecorder","Sound Recorder"}})button(tool[1],()->open.accept(tool[0]));button("Calculator",()->open.accept("@gadget:calculator"));button("Unit converter",()->open.accept("@gadget:converter"));button("Text counter",()->open.accept("@gadget:textcounter"));break;
            case "games":button("Tile puzzle",()->open.accept("@gadget:puzzle"));button("Dice roller",()->open.accept("@gadget:dice"));break;
            case "assistant":note("Nth Nota can open apps, find files, search the web and help with writing. Local commands work on this device; cloud writing assistance is optional.");button("Open Nth Nota",()->open.accept("@nota"));break;
            case "clipboard":note((ExplorerClipboard.files.size()+ExplorerClipboard.shortcuts.size())+" copied file or shortcut items");button("Clear launcher clipboard",()->{ExplorerClipboard.files.clear();ExplorerClipboard.shortcuts.clear();render();});break;
            case "about":showDetails("system");break;
            case "startup":showDetails("startup");break;
            case "clock":showDetails("clock");break;
            case "taskbarapps":showDetails("taskbar");break;
            case "backgroundoptions":showDetails("background");break;
            case "backup":button("Backup and restore Eight",()->open.accept("@backup"));break;
            case "recovery":button("Guided setup",()->open.accept("@welcome"));button("Restart Nth Desktop",()->open.accept("setting:restart-desktop"));break;
        }
    }
    void openProfile(){EditText name=new EditText(getContext());name.setSingleLine();name.setText(store.prefs.getString("desktop_name","Nth Experience"));name.setContentDescription("Desktop profile name");body.addView(name);button("Save name",()->{String value=name.getText().toString().trim();if(value.isEmpty()||value.length()>60){name.setError("Use 1–60 characters");return;}store.prefs.edit().putString("desktop_name",value).apply();appearanceChanged();});button("Choose profile picture",()->open.accept("setting:page:accounts"));}
    void heading(String s){TextView t=Aero.text(getContext(),s,23,0xff215a8a);t.setPadding(0,dp(8),0,dp(18));body.addView(t);}
    void note(String s){TextView t=Aero.text(getContext(),s,14,0xff333333);t.setPadding(0,dp(5),0,dp(14));body.addView(t);}
    TextView buttonText(String s,Runnable action){TextView t=Aero.text(getContext(),s,14,0xff155b91);t.setPadding(dp(9),dp(10),dp(9),dp(10));t.setMinHeight(dp(44));t.setFocusable(true);t.setContentDescription(s);t.setBackground(Aero.selection(getContext()));t.setOnClickListener(v->action.run());return t;}
    void button(String s,Runnable action){body.addView(buttonText(s,action),new LayoutParams(-1,-2));}
    CheckBox toggle(String s,String key,boolean fallback){CheckBox t=new CheckBox(getContext());t.setText(s);t.setTextColor(Color.BLACK);t.setContentDescription(s);t.setChecked(store.prefs.getBoolean(key,fallback));t.setMinHeight(dp(48));t.setOnCheckedChangeListener((v,on)->{store.prefs.edit().putBoolean(key,on).apply();appearanceChanged();});body.addView(t,new LayoutParams(-1,-2));return t;}
    void choice(String label,String key,String[] values,String fallback){button(label+": "+store.prefs.getString(key,fallback),()->Aero.dialog(getContext()).setTitle(label).setItems(values,(d,n)->{store.prefs.edit().putString(key,values[n]).apply();appearanceChanged();}).show());}
    @Override protected void onDetachedFromWindow(){if(preview!=null)preview.close();if(details!=null)details.close();super.onDetachedFromWindow();}
}
